function lockBodyScroll(){savedScrollPos=window.scrollY||window.pageYOffset;document.body.style.top='-'+savedScrollPos+'px';document.body.classList.add('reset-modal-open','no-scroll');document.body.style.overflow='hidden';document.body.style.position='fixed';document.body.style.width='100%';document.body.style.height='100%';}
