function openIDB(){if(idbInstance)return Promise.resolve(idbInstance);return new Promise((res,rej)=>{try{const req=indexedDB.open(IDB,IDBV);req.onupgradeneeded=e=>{const db=e.target.result;if(!db.objectStoreNames.contains('texts'))db.createObjectStore('texts',{keyPath:'key'});if(!db.objectStoreNames.contains('tafsir'))db.createObjectStore('tafsir',{keyPath:'key'});if(!db.objectStoreNames.contains('meta'))db.createObjectStore('meta',{keyPath:'key'});if(!db.objectStoreNames.contains('timings'))db.createObjectStore('timings',{keyPath:'key'});};req.onsuccess=()=>{idbInstance=req.result;res(idbInstance);};req.onerror=()=>rej(req.error);}catch(e){rej(e);}});}
async function idbGet(s,k){try{const db=await openIDB();return new Promise(r=>{const tx=db.transaction(s,'readonly'),req=tx.objectStore(s).get(k);req.onsuccess=()=>{const v=req.result;r(v&&typeof v==='object'&&'value'in v?v.value:(v||null));};req.onerror=()=>r(null);});}catch(e){return null;}}
async function idbPut(s,k,v){try{const db=await openIDB();return new Promise(r=>{const tx=db.transaction(s,'readwrite');tx.objectStore(s).put({key:k,value:v,ts:Date.now()});tx.oncomplete=()=>r(true);tx.onerror=()=>r(false);});}catch(e){return false;}}
async function idbDelete(s,k){try{const db=await openIDB();return new Promise(r=>{const tx=db.transaction(s,'readwrite');tx.objectStore(s).delete(k);tx.oncomplete=()=>r(true);tx.onerror=()=>r(false);});}catch(e){return false;}}
async function idbHas(s,k){const v=await idbGet(s,k);return v!=null;}
async function idbClear(s){try{const db=await openIDB();return new Promise(r=>{const tx=db.transaction(s,'readwrite');tx.objectStore(s).clear();tx.oncomplete=()=>r(true);tx.onerror=()=>r(false);});}catch(e){return false;}}
async function idbGetAllKeys(s){try{const db=await openIDB();return new Promise(r=>{const tx=db.transaction(s,'readonly'),req=tx.objectStore(s).getAllKeys();req.onsuccess=()=>r(req.result||[]);req.onerror=()=>r([]);});}catch(e){return[];}}
async function idbGetAll(s){try{const db=await openIDB();return new Promise(r=>{const tx=db.transaction(s,'readonly'),req=tx.objectStore(s).getAll();req.onsuccess=()=>r(req.result||[]);req.onerror=()=>r([]);});}catch(e){return[];}}
async function loadTimingData(readerId,surahIdx){const readId=SYNC_READERS[readerId];if(!readId)return null;const ck='timing_'+readerId+'_'+surahIdx;try{const cached=await idbGet('timings',ck);if(cached&&cached.verse_timings&&cached.verse_timings.length>0)return cached;}catch(e){}try{const url=SYNC_BASE_URL+'?surah='+(surahIdx+1)+'&read='+readId;const r=await fetchWithTimeout(url,{timeout:10000});if(!r.ok)return null;const data=await r.json();if(Array.isArray(data)&&data.length>0&&data[0].ayah!==undefined){const zeroStart=data[0].ayah===0;const verse_timings=data.map(a=>({verse_key:(surahIdx+1)+':'+(zeroStart?a.ayah+1:a.ayah),timestamp_from:a.start_time,timestamp_to:a.end_time}));let totalGap=0,gapCount=0;for(let i=1;i<verse_timings.length;i++){const gap=verse_timings[i].timestamp_from-verse_timings[i-1].timestamp_to;if(gap>=0&&gap<3000){totalGap+=gap;gapCount++;}}const avg_gap=gapCount>0?Math.round(totalGap/gapCount):0;const normalized={verse_timings:verse_timings,avg_gap:avg_gap};idbPut('timings',ck,normalized);return normalized;}}catch(e){}return null;}
async function migrateLS(){if(localStorage.getItem('idb_migration_v5_done')==='true')return;try{const tks=Object.keys(localStorage).filter(k=>k.startsWith('quranText_'));for(const k of tks){try{const p=JSON.parse(localStorage.getItem(k));if(p&&p.html){await idbPut('texts',k,p);localStorage.removeItem(k);}}catch(e){}}const tfs=Object.keys(localStorage).filter(k=>k.startsWith('quranTafsir_'));for(const k of tfs){try{const p=JSON.parse(localStorage.getItem(k));if(p&&p.data){await idbPut('tafsir',k,p);localStorage.removeItem(k);}}catch(e){}}const qt=localStorage.getItem('quranTexts');if(qt){try{const p=JSON.parse(qt);if(Array.isArray(p)&&p.length>0){await idbPut('meta','quranTexts',p);localStorage.removeItem('quranTexts');}}catch(e){}}localStorage.setItem('idb_migration_v5_done','true');}catch(e){}}
