const formatSize=b=>{if(!b)return'غير معروف';const u=['ب','ك.ب','م.ب','ج.ب'];const i=Math.floor(Math.log(b)/Math.log(1024));return (b/Math.pow(1024,i)).toFixed(1)+' '+u[i];};
