function applyTheme(mode){darkMode=(mode==='dark');const s=darkMode?DS:LS,r=document.documentElement;Object.keys(s).forEach(k=>r.style.setProperty(k,s[k]));const meta=$('themeColorMeta');if(meta)meta.content=darkMode?'#0d0d0d':'#ebe3d6';const lb=$('themeLight'),db=$('themeDark');if(lb)lb.classList.toggle('active',!darkMode);if(db)db.classList.toggle('active',darkMode);try{localStorage.setItem('darkMode',mode);}catch(e){}r.classList.toggle('dark',darkMode);applyColor(currentColor);applyMushafTheme();debouncedSaveState();}
function applyColor(color){if(!CS[color]){color='gold';}currentColor=color;const s=CS[color][darkMode?'dark':'light'],r=document.documentElement;r.style.setProperty('--gold',s.main);r.style.setProperty('--gold-light',s.light);r.style.setProperty('--gold-dark',s.dark);r.style.setProperty('--gold-rgb',hexToRgb(s.main));localStorage.setItem('accentColor',color);document.querySelectorAll('#colorPicker .color-dot').forEach(d=>d.classList.toggle('active',d.dataset.color===color));}
function loadFontFamily(font){const r=document.documentElement,t=$('fontSelectTrigger');if(font==='system'){currentFont='system';r.style.setProperty('--font-family',"'Traditional Arabic','Arial',sans-serif");r.style.setProperty('--font-ui',"'Tajawal','Arial',sans-serif");if(t)t.textContent='نظام (تقليدي)';document.querySelectorAll('#fontSelectOptions .custom-select-option').forEach(o=>o.classList.toggle('selected',o.dataset.value==='system'));localStorage.setItem('quranFont','system');return;}const lid='google-font-'+font.replace(/\s/g,'');if(!$(lid)){const l=document.createElement('link');l.id=lid;l.rel='stylesheet';l.href='https://fonts.googleapis.com/css2?family='+encodeURIComponent(font)+'&display=swap';document.head.appendChild(l);}currentFont=font;r.style.setProperty('--font-family',"'"+font+"',serif");r.style.setProperty('--font-ui',"'"+font+"',sans-serif");const opts=document.querySelectorAll('#fontSelectOptions .custom-select-option');if(t){const so=Array.from(opts).find(o=>o.dataset.value===font);t.textContent=so?so.textContent:font;}opts.forEach(o=>o.classList.toggle('selected',o.dataset.value===font));localStorage.setItem('quranFont',font);}
