function showToast(msg,type='default',duration=2000){const t=$('toast');if(!t)return;t.className='toast';if(type&&type!=='default')t.classList.add(type);const clean=msg.replace(/^[✅❌⚠ℹ🗑⏳⏹🔄▶⬇]+\s*/,'');const iconMap={success:'ic-check-circle',error:'ic-times-circle',warning:'ic-exclamation-triangle',info:'ic-info-circle'};const prefix=iconMap[type]?svgIcon(iconMap[type]):'';t.innerHTML='<span>'+prefix+clean+'</span>';t.classList.add('show');clearTimeout(t._timer);if(duration>0)t._timer=setTimeout(()=>t.classList.remove('show'),duration);}
