async function fetchVersionData(){try{const c=new AbortController(),tid=setTimeout(()=>c.abort(),10000);const r=await fetch(UPD_URL,{cache:'no-store',signal:c.signal});clearTimeout(tid);if(!r.ok)return null;const d=await r.json();return d;}catch(e){return null;}}
function hasChangelogData(changelog){if(!changelog)return false;if(Array.isArray(changelog))return changelog.length>0;if(typeof changelog==='object')return Object.keys(changelog).length>0;if(typeof changelog==='string')return changelog.trim().length>0;return false;}
function normalizeChangelog(changelog){if(!changelog)return[];if(Array.isArray(changelog))return changelog;if(typeof changelog==='object')return [changelog];return[];}
async function checkForAppUpdate(){if(!networkOnline)return;const d=await fetchVersionData();if(!d)return;const rv=parseInt(d.version,10);if(!isNaN(rv)&&rv>VER){updateData=d;showUpdateDialog(rv,d.url,d.changelog);}}
function showUpdateDialog(v,url,changelog){const cm=$('updCurrentVer'),nm=$('updNewVer');if(cm)cm.textContent=VER;if(nm)nm.textContent=v;const body=$('updChangelog');if(body){if(hasChangelogData(changelog)){body.innerHTML=renderChangelogHtml(normalizeChangelog(changelog),true);}else{body.innerHTML='<div class="cl-simple-msg">'+svgIcon('ic-download')+'ننصحك بتحديث التطبيق للحصول على آخر التحسينات والإصلاحات.</div>';}}openModalUniversal('updModal');const btn=$('updNow');if(btn)btn.onclick=()=>{window.open(url||'https://mamhaz.github.io/QuranKarim/QuranKarimv50.apk','_blank');closeModalUniversal('updModal');};const later=$('updLater');if(later)later.onclick=()=>closeModalUniversal('updModal');}
function renderChangelogHtml(changelog,compact){if(!changelog||!changelog.length)return '<div class="cl-empty">لا توجد تحديثات</div>';let h='';changelog.slice(0,compact?1:10).forEach(v=>{h+='<div class="cl-version"><div class="cl-version-header"><span class="cl-badge">v'+escapeHtml(v.version||'')+'</span></div>';if(v.title)h+='<div class="cl-title">'+escapeHtml(v.title)+'</div>';if(v.groups&&v.groups.length){v.groups.forEach(g=>{h+='<div class="cl-group"><div class="cl-group-title">'+escapeHtml(g.name)+'</div>';if(g.items&&g.items.length){h+='<ul class="cl-items">';g.items.forEach(it=>{h+='<li>'+escapeHtml(it)+'</li>';});h+='</ul>';}h+='</div>';});}else if(v.items&&v.items.length){h+='<ul class="cl-items">';v.items.forEach(it=>{h+='<li>'+escapeHtml(it)+'</li>';});h+='</ul>';}h+='</div>';});return h;}
