function openContactModal(){const m=$('contactModal');if(!m)return;const f=$('contactForm');if(f)f.reset();contactSelectedType='suggestion';updateContactTypeUI();const err=$('ctError');if(err){err.textContent='';err.classList.remove('show');}const dev=$('ctDevice');if(dev)dev.value=(navigator.userAgent||'').slice(0,120);const sub=$('contactSubmit');if(sub){sub.classList.remove('loading');sub.disabled=false;sub.innerHTML=svgIcon('ic-paper-plane')+' إرسال';}openModalUniversal('contactModal');setTimeout(()=>{const n=$('ctName');if(n)n.focus();},350);}
