async function submitContactForm(e){e.preventDefault();const f=$('contactForm');const err=$('ctError');const btn=$('contactSubmit');if(!f||!btn)return;const name=$('ctName').value.trim();const email=$('ctEmail').value.trim();const message=$('ctMessage').value.trim();if(!name){showContactError('الرجاء إدخال الاسم');return;}if(!message||message.length<5){showContactError('الرجاء إدخال رسالة (5 أحرف على الأقل)');return;}if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){showContactError('البريد الإلكتروني غير صحيح');return;}if(err)err.classList.remove('show');btn.classList.add('loading');btn.disabled=true;btn.innerHTML=svgIcon('ic-sync')+' جاري الإرسال...';try{const entry=CONTACT_TYPE_LABELS[contactSelectedType]||{label:contactSelectedType};const typeLabel=entry.label;const fd=new FormData();fd.append('name',name);if(email)fd.append('email',email);fd.append('type',typeLabel);fd.append('message',message);fd.append('_subject','رسالة '+typeLabel+' — من '+name);fd.append('app_version','5.0');fd.append('user_device',(navigator.userAgent||'').slice(0,120));const r=await fetch(FORMSPREE_URL,{method:'POST',body:fd,headers:{Accept:'application/json'}});if(!r.ok)throw new Error('fail');const box=f.parentElement;box.innerHTML='<div class="form-success">'+svgIcon('ic-check-circle')+'<h4>تم إرسال رسالتك بنجاح</h4><p>شكراً لتواصلك معنا، سنراجع رسالتك ونأخذها بعين الاعتبار.<br>جزاك الله خيراً</p><button class="btn-close-modal" id="contactDone" style="width:100%;margin-top:1.2rem;">إغلاق</button></div>';const done=$('contactDone');if(done)done.onclick=()=>{closeContactModal();setTimeout(()=>location.reload(),200);};toastSuccess('تم استلام رسالتك، شكراً لك');}catch(ex){btn.classList.remove('loading');btn.disabled=false;btn.innerHTML=svgIcon('ic-paper-plane')+' إرسال';showContactError('تعذر الإرسال، تحقق من اتصالك بالإنترنت وحاول مرة أخرى.');}}
window.addEventListener('online',()=>{if(!networkOnline){networkOnline=true;updateNetworkIndicator();toastInfo('تم استعادة الاتصال بالإنترنت');if(verifyCancelFlag){verifyCancelFlag=false;startCheckingAvailability();}}});
window.addEventListener('offline',()=>{if(networkOnline){networkOnline=false;updateNetworkIndicator();toastWarning('تم فقدان الاتصال بالإنترنت');}});
function checkNetworkViaPing(){if(!isWebViewEnv&&networkOnline)return;if(networkCheckAbort){try{networkCheckAbort.abort();}catch(e){}}const c=new AbortController();networkCheckAbort=c;const tid=setTimeout(()=>{try{c.abort();}catch(e){}},5000);let success=false;['https://www.google.com/favicon.ico','https://www.cloudflare.com/favicon.ico','https://1.1.1.1/cdn-cgi/trace'].forEach((url,i)=>{if(success)return;fetch(url,{method:'HEAD',signal:c.signal,cache:'no-store',mode:'no-cors'}).then(()=>{clearTimeout(tid);if(!success){success=true;if(!networkOnline){networkOnline=true;updateNetworkIndicator();toastInfo('تم استعادة الاتصال بالإنترنت');if(verifyCancelFlag){verifyCancelFlag=false;startCheckingAvailability();}}networkCheckAbort=null;}}).catch(err=>{if(err.name==='AbortError'){clearTimeout(tid);networkCheckAbort=null;return;}if(i===2&&!success){clearTimeout(tid);if(networkOnline){networkOnline=false;updateNetworkIndicator();toastWarning('تم فقدان الاتصال بالإنترنت');}networkCheckAbort=null;}});});}
function startNetworkPolling(){if(networkPollingInterval)clearInterval(networkPollingInterval);checkNetworkViaPing();networkPollingInterval=setInterval(()=>{if(!document.hidden)checkNetworkViaPing();},isWebViewEnv?3000:10000);}
function updateNetworkIndicator(){const i=$('networkIndicator'),s=$('networkStatus');if(!i||!s)return;if(networkOnline){i.className='network-indicator online';s.innerHTML=svgIcon('ic-wifi');s.title='متصل بالإنترنت';}else{i.className='network-indicator offline';s.innerHTML='<div style="position:relative;display:inline-block;">'+svgIcon('ic-wifi')+'<svg class="ic" style="position:absolute;top:-6px;right:-6px;font-size:0.8rem;color:#e74c3c;background:var(--bg);border-radius:50%;padding:1px;"><use href="#ic-times"/></svg></div>';s.title='غير متصل بالإنترنت';}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden){document.body.classList.remove('page-hidden');checkNetworkViaPing();if(!networkPollingInterval)startNetworkPolling();}else{document.body.classList.add('page-hidden');if(networkPollingInterval){clearInterval(networkPollingInterval);networkPollingInterval=null;}if(networkCheckAbort){try{networkCheckAbort.abort();}catch(e){}networkCheckAbort=null;}}});
$('networkIndicator').addEventListener('click',()=>{if(networkOnline)toastInfo('متصل بالإنترنت');else{toastWarning('غير متصل بالإنترنت');checkNetworkViaPing();}});
function debouncedSaveState(){if(saveTimeout)clearTimeout(saveTimeout);saveTimeout=setTimeout(()=>{saveState();saveTimeout=null;},300);}
function saveState(){localStorage.setItem('currentReader',currentReader);localStorage.setItem('favSurahs',JSON.stringify(favSurahs));localStorage.setItem('favReaders',JSON.stringify(favReaders));localStorage.setItem('downloadedSurahs',JSON.stringify(downloaded));localStorage.setItem('playSpeed',String(speed));localStorage.setItem('playerVolume',String(volume));localStorage.setItem('quranFontSize',String(fontsize));localStorage.setItem('quranFont',currentFont);localStorage.setItem('darkMode',darkMode?'dark':'light');localStorage.setItem('accentColor',currentColor);localStorage.setItem('playerPinned',String(isPlayerPinned));if(currentSurah>=0&&audio.src&&audio.duration){const t=audio.currentTime||0;if(t<audio.duration)localStorage.setItem('lastPlay',JSON.stringify({reader:currentReader,surah:currentSurah,time:t,timestamp:Date.now()}));}}
function restoreLast(){const l=localStorage.getItem('lastPlay');if(l){try{const d=JSON.parse(l);if(d.reader===currentReader&&d.surah>=0&&d.surah<114){lastSurah=d.surah;lastTime=d.time||0;if(lastTime<0)lastTime=0;}}catch(e){}}}
function saveReadingState(s,a){try{localStorage.setItem('lastReading',JSON.stringify({surah:s,ayah:a,timestamp:Date.now()}));}catch(e){}}
async function syncSurahWithCache(rid,idx){const url=getReaderUrl(rid,idx);if(!url)return false;try{const c=await caches.open('quran-audio'),cached=await c.match(url),isInCache=!!cached;if(isInCache){let size=0;try{const b=await cached.blob();size=b.size;}catch(e){}if(!downloaded[rid])downloaded[rid]={};if(!downloaded[rid][idx]||!downloaded[rid][idx].downloaded||downloaded[rid][idx].size!==size){downloaded[rid][idx]={downloaded:true,size:size||0,date:new Date().toISOString(),lastPlayedAt:downloaded[rid][idx]?.lastPlayedAt||null};debouncedSaveState();}}else if(downloaded[rid]?.[idx]?.downloaded){delete downloaded[rid][idx];debouncedSaveState();}return isInCache;}catch(e){return downloaded[rid]?.[idx]?.downloaded||false;}}
async function calculateAllSurahSizes(){try{const c=await caches.open('quran-audio'),keys=await c.keys();let updated=0;for(const req of keys){const url=req.url;for(const reader of R){if(url.startsWith(reader.url)){const idx=parseInt(url.replace(reader.url,'').replace('.mp3',''))-1;if(idx>=0&&idx<114){const resp=await c.match(req);if(resp){try{const b=await resp.blob();if(b.size>0){if(!downloaded[reader.id])downloaded[reader.id]={};if(!downloaded[reader.id][idx]||downloaded[reader.id][idx].size!==b.size){downloaded[reader.id][idx]={downloaded:true,size:b.size,date:downloaded[reader.id][idx]?.date||new Date().toISOString(),lastPlayedAt:downloaded[reader.id][idx]?.lastPlayedAt||null};updated++;}}}catch(e){}}}break;}}}if(updated>0)debouncedSaveState();}catch(e){}}
async function getCachedUrl(url){try{const c=await caches.open('quran-audio'),cached=await c.match(url);if(cached)return URL.createObjectURL(await cached.blob());}catch(e){}return null;}
let quranTextsLoadingPromise=null;
async function loadQuranTexts(){if(quranTexts&&quranTexts.length===114)return quranTexts;if(quranTextsLoadingPromise)return quranTextsLoadingPromise;quranTextsLoadingPromise=(async()=>{try{const c=await idbGet('meta','quranTexts');if(c&&Array.isArray(c)&&c.length===114){quranTexts=c;return quranTexts;}}catch(e){}const temp=[];toastInfo('جاري تحميل النص القرآني...');for(let i=1;i<=114;i++){try{const c=new AbortController(),tid=setTimeout(()=>c.abort(),15000);const r=await fetch('https://api.alquran.cloud/v1/surah/'+i+'/quran-simple',{signal:c.signal});clearTimeout(tid);const d=await r.json();if(d?.data?.ayahs){temp.push({surah:i,name:SN[i-1],ayahs:d.data.ayahs.map((a,idx)=>({number:idx+1,text:a.text,normalized:normalizeText(a.text)}))});}}catch(e){}}quranTexts=temp;if(quranTexts.length===114){idbPut('meta','quranTexts',quranTexts);}else if(quranTexts.length>0){toastWarning('تم تحميل '+quranTexts.length+' سورة فقط');}quranTextsLoadingPromise=null;return quranTexts;})();return quranTextsLoadingPromise;}
async function searchAyahInAllQuran(query){if(!quranTexts||quranTexts.length===0)await loadQuranTexts();if(!query||query.length<2)return[];const results=[],ph=normalizeText(query);if(!ph)return[];let processed=0;for(const surah of quranTexts){for(const ayah of surah.ayahs){const nt=ayah.normalized||normalizeText(ayah.text);if(nt.includes(ph))results.push({surah:surah.surah,surahName:surah.name,ayah:ayah.number,text:ayah.text,score:1});processed++;if(processed%500===0)await new Promise(r=>setTimeout(r,0));}}return results;}
function highlightText(text,query){const terms=normalizeText(query).split(' ').filter(t=>t.length>0);let r=escapeHtml(text);for(const t of terms){const et=t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');r=r.replace(new RegExp(et,'gi'),m=>'<span class="highlight-term">'+m+'</span>');}return r;}
function generateMushafHtml(ayahs,surahNum,surahName,targetAyah){const pages={},order=[];ayahs.forEach(a=>{const p=a.page||1;if(!pages[p]){pages[p]=[];order.push(p);}pages[p].push(a);});order.sort((a,b)=>a-b);const f=MUSHAF_FONTS.find(x=>x.id===mushafFont)||MUSHAF_FONTS[0];let html='<div class="m-wrap'+(mushafViewMode==='continuous'?' continuous':'')+'">';order.forEach((p,pi)=>{html+='<div class="m-page"><div class="m-frame">';if(pi===0){html+='<div class="m-band"><span>سورة '+surahName+'</span></div>';if(surahNum!==1&&surahNum!==9){html+='<div class="m-bs">بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ</div>';}}html+='<div class="m-tx" style="font-size:'+fontsize+'rem;font-family:'+f.css+';line-height:'+mushafLineHeight+'">';pages[p].forEach(a=>{let txt=a.text;if(pi===0&&a.numberInSurah===1&&surahNum!==1&&surahNum!==9){const marker='ٱلرَّحِيمِ';const i=txt.indexOf(marker);if(i!==-1)txt=txt.substring(i+marker.length).trim();}const tgt=targetAyah&&+targetAyah===a.numberInSurah;html+='<span class="ayah-line'+(tgt?' hl':'')+'" data-s="'+surahNum+'" data-a="'+a.numberInSurah+'" data-text="'+escapeHtml(txt)+'">'+txt+'<span class="an">'+arNum(a.numberInSurah)+'</span></span> ';});html+='</div>';html+='<div class="m-num"><span class="num-orn">۞</span>'+arNum(p)+'<span class="num-orn">۞</span></div>';html+='</div></div>';});html+='</div>';return html;}
async function getTafsirFromFile(surah,ayah){const CSZ=50,BASE='https://raw.githubusercontent.com/MAmhaz/QuranKarim/main/Data2/';const isLong=(AYAH_COUNTS[surah]||0)>CSZ;let url='';if(isLong){const p=Math.ceil(ayah/CSZ);url=BASE+'tafsir_'+surah+'_part'+p+'.json';}else url=BASE+'tafsir_'+surah+'.json';const ck='tafsir_'+surah+(isLong?'_part'+Math.ceil(ayah/CSZ):'');let data=null;if(tafsirCache.has(ck))data=tafsirCache.get(ck);else{try{const id=await idbGet('tafsir','quranTafsir_'+ck);if(id){data=id;lruSet(tafsirCache,ck,data);}}catch(e){}if(!data){try{const r=await fetch(url);if(!r.ok)throw new Error('fail');data=await r.json();lruSet(tafsirCache,ck,data);idbPut('tafsir','quranTafsir_'+ck,data);}catch(e){return{text:'حدث خطأ في تحميل التفسير',mufassir:'تفسير الميزان'};}}}const ad=data[ayah];if(!ad)return{text:'الآية غير موجودة في هذا التفسير',mufassir:'تفسير الميزان'};return{text:ad['layer1_ar']||'التفسير غير متوفر',mufassir:'تفسير الميزان (العلامة الطباطبائي)'};}
async function getTafsirFromApi(surah,ayah,code){try{const c=new AbortController(),tid=setTimeout(()=>c.abort(),8000);const r=await fetch('https://api.alquran.cloud/v1/ayah/'+surah+':'+ayah+'/'+code,{signal:c.signal});clearTimeout(tid);if(!r.ok)throw new Error('fail');const d=await r.json();return d?.data?.text||'التفسير غير متوفر';}catch(e){return null;}}
async function fetchTafsir(surah,ayah,source){const info=TAFSIR_SOURCES[source]||TAFSIR_SOURCES.mizan;if(info.type==='file'){return await getTafsirFromFile(surah,ayah);}const txt=await getTafsirFromApi(surah,ayah,info.code);if(txt===null)return{text:'تعذر تحميل التفسير، تحقق من اتصالك بالإنترنت',mufassir:info.name+' — '+info.author};return{text:txt,mufassir:info.name+' — '+info.author};}
async function renderAllSurahs(force=false){if(isRendering)return;if(!force&&!isInitialRender&&document.querySelector('.surah-card'))return;isRendering=true;isInitialRender=false;try{const grid=$('surahGrid');if(!grid){isRendering=false;return;}grid.innerHTML='';const rid=currentReader;if(!surahAvailability[rid])surahAvailability[rid]={};for(let i=0;i<TOTAL;i++){if(!surahAvailability[rid][i])surahAvailability[rid][i]='pending';const isInCache=await syncSurahWithCache(rid,i);const card=document.createElement('div');card.className='surah-card';card.dataset.idx=i;const isFav=favSurahs.indexOf(i)!==-1;const isPartial=downloadProgress[rid]&&downloadProgress[rid][i]!==undefined&&downloadProgress[rid][i]<100;const status=surahAvailability[rid][i];let btnHtml='';if(isPartial){const pct=Math.round(downloadProgress[rid][i]);btnHtml='<button class="download-btn downloading" data-idx="'+i+'" data-action="resume"><svg class="progress-ring" viewBox="0 0 40 40"><circle class="bg" cx="20" cy="20" r="16"/><circle class="fg" cx="20" cy="20" r="16" stroke-dasharray="100.53" stroke-dashoffset="'+(100.53*(1-pct/100))+'"/></svg><span class="progress-text">'+pct+'%</span><span class="cancel-icon" data-idx="'+i+'">×</span></button>';}else if(isInCache){btnHtml='<button class="download-btn downloaded" data-idx="'+i+'" title="حذف التنزيل">'+svgIcon('ic-check-circle')+'</button>';}else{let cls='download-btn';if(status==='unavailable')cls+=' unavailable not-exist';else if(status==='failed')cls+=' verify-failed';else if(status==='pending')cls+=' verify-pending';btnHtml='<button class="'+cls+'" data-idx="'+i+'">'+svgIcon('ic-download')+'</button>';}const showStatusRow=(status==='unavailable'||status==='failed'||status==='pending');const showRetry=(status==='failed');card.innerHTML='<div class="surah-main-row"><span class="surah-number">'+(i+1)+'</span><span class="surah-name">'+SN[i]+'</span><div class="surah-actions"><button class="play-btn" data-idx="'+i+'">'+svgIcon('ic-play')+'</button><button class="read-btn" data-idx="'+i+'">'+svgIcon('ic-book-open')+'</button><button class="fav-btn '+(isFav?'active':'')+'" data-idx="'+i+'">'+svgIcon(isFav?'ic-star-fill':'ic-star')+'</button>'+btnHtml+'</div></div><div class="surah-status-row" style="'+(showStatusRow?'':'display:none;')+'"><span class="unavailability-badge">'+svgIcon('ic-times-circle')+' غير موجودة في المصدر</span><span class="warning-badge">'+svgIcon('ic-exclamation-triangle')+' '+(networkOnline?'فشل التحقق':'لا يوجد اتصال')+'</span>'+(showRetry?'<button class="retry-check-btn" data-idx="'+i+'">'+svgIcon('ic-sync')+' '+(networkOnline?'إعادة المحاولة':'انتظر الاتصال')+'</button>':'')+'</div>';grid.appendChild(card);}grid.addEventListener('click',handleSurahAction);for(let j=0;j<TOTAL;j++)await updateSurahCardStatus(j);startCheckingAvailability();}catch(e){}finally{isRendering=false;}}
async function updateSurahCardStatus(idx){const rid=currentReader,card=document.querySelector('.surah-card[data-idx="'+idx+'"]');if(!card)return;const isInCache=await syncSurahWithCache(rid,idx);const statusRow=card.querySelector('.surah-status-row'),badge=card.querySelector('.unavailability-badge'),warningBadge=card.querySelector('.warning-badge'),spinner=card.querySelector('.checking-spinner'),downloadBtn=card.querySelector('.download-btn'),playBtn=card.querySelector('.play-btn'),retryBtn=card.querySelector('.retry-check-btn');const status=surahAvailability[rid]?.[idx];if(badge)badge.classList.remove('show');if(warningBadge)warningBadge.classList.remove('show');if(spinner)spinner.classList.remove('show');if(retryBtn)retryBtn.classList.remove('show');if(downloadBtn){downloadBtn.classList.remove('unavailable','verify-failed','verify-pending','not-exist','downloaded','downloading');}if(playBtn){playBtn.classList.remove('disabled','verify-pending');playBtn.style.opacity='1';playBtn.title='تشغيل السورة';}card.className='surah-card';const isPartial=downloadProgress[rid]?.[idx]!==undefined&&downloadProgress[rid][idx]<100;if(isInCache){downloadBtn.classList.add('downloaded');downloadBtn.innerHTML=svgIcon('ic-check-circle');downloadBtn.title='حذف التنزيل';statusRow.style.display='none';playBtn.title='تشغيل السورة (محلية)';card.classList.add('status-cached');return;}if(isPartial){const pct=Math.round(downloadProgress[rid][idx]);downloadBtn.classList.add('downloading');downloadBtn.innerHTML='<svg class="progress-ring" viewBox="0 0 40 40"><circle class="bg" cx="20" cy="20" r="16"/><circle class="fg" cx="20" cy="20" r="16" stroke-dasharray="100.53" stroke-dashoffset="'+(100.53*(1-pct/100))+'"/></svg><span class="progress-text">'+pct+'%</span><span class="cancel-icon" data-idx="'+idx+'">×</span>';downloadBtn.title='استئناف التنزيل';statusRow.style.display='none';return;}switch(status){case 'available':statusRow.style.display='none';downloadBtn.innerHTML=svgIcon('ic-download');downloadBtn.title='تنزيل السورة';card.classList.add('status-available');break;case 'cached':statusRow.style.display='none';playBtn.title='تشغيل السورة (من الذاكرة)';downloadBtn.innerHTML=svgIcon('ic-download');downloadBtn.title='تنزيل السورة';card.classList.add('status-cached');break;case 'unavailable':badge.innerHTML=svgIcon('ic-times-circle')+' غير موجودة في المصدر';badge.classList.add('show');statusRow.style.display='flex';playBtn.classList.add('disabled');playBtn.style.opacity='0.3';downloadBtn.classList.add('unavailable','not-exist');card.classList.add('status-unavailable');break;case 'pending':statusRow.style.display='flex';playBtn.classList.add('verify-pending');playBtn.style.opacity='0.6';downloadBtn.classList.add('verify-pending');downloadBtn.innerHTML=svgIcon('ic-download');card.classList.add('status-pending');break;case 'failed':warningBadge.innerHTML=networkOnline?svgIcon('ic-exclamation-triangle')+' فشل التحقق':svgIcon('ic-exclamation-triangle')+' لا يوجد اتصال';warningBadge.classList.add('show');retryBtn.classList.add('show');retryBtn.innerHTML=networkOnline?svgIcon('ic-sync')+' إعادة المحاولة':svgIcon('ic-wifi')+' انتظر الاتصال';statusRow.style.display='flex';downloadBtn.innerHTML=svgIcon('ic-download');card.classList.add('status-failed');break;default:statusRow.style.display='none';downloadBtn.innerHTML=svgIcon('ic-download');}}
function handleSurahAction(e){const t=e.target.closest('button');if(!t)return;const card=t.closest('.surah-card');if(!card)return;const idx=parseInt(card.dataset.idx);if(isNaN(idx))return;e.stopPropagation();if(t.classList.contains('play-btn'))playSurah(idx,0);else if(t.classList.contains('read-btn'))openReader(idx);else if(t.classList.contains('fav-btn'))toggleFavSurah(idx);else if(t.classList.contains('download-btn')){const isDl=downloaded[currentReader]?.[idx]?.downloaded;if(isDl){showDeleteConfirm(idx);return;}if(idx<0||idx>113){toastError('رقم سورة غير صحيح');return;}const did=currentReader+'_'+idx;if(activeDownloads[did]){showAlertHtml(svgIcon('ic-hourglass')+' التحميل جارٍ بالفعل لسورة <strong>"'+SN[idx]+'"</strong>.<br>هل تريد إلغاء التحميل؟',()=>{const di=activeDownloads[did];if(di?.xhr)di.xhr.abort();toastInfo('تم إلغاء تحميل "'+SN[idx]+'"');if(downloadProgress[currentReader])delete downloadProgress[currentReader][idx];updateSurahCardStatus(idx);});return;}showDownloadConfirm(idx);}else if(t.classList.contains('retry-check-btn')){const i2=parseInt(t.dataset.idx);if(!isNaN(i2)){if(!networkOnline){toastWarning('لا يوجد اتصال بالإنترنت');return;}if(surahAvailability[currentReader])delete surahAvailability[currentReader][i2];toastInfo('جاري إعادة التحقق...');t.classList.add('checking');enqueueVerify(currentReader,i2);const ci=setInterval(()=>{const ns=surahAvailability[currentReader]?.[i2];if(ns&&ns!=='pending'){clearInterval(ci);t.classList.remove('checking');if(ns==='available'||ns==='cached')toastSuccess('السورة متوفرة');else if(ns==='unavailable')toastWarning('السورة غير موجودة في المصدر');else if(ns==='failed')toastError('فشل التحقق، تأكد من اتصالك بالإنترنت');}},500);setTimeout(()=>{clearInterval(ci);t.classList.remove('checking');},15000);}}else if(t.classList.contains('cancel-icon')){const i3=parseInt(t.dataset.idx);if(!isNaN(i3))cancelPartialDownload(i3);}}
function enqueueVerify(rid,idx){verifyQueue.push({readerId:rid,idx:idx});processVerifyQueue();}
function processVerifyQueue(){while(verifyActive<CONC&&verifyQueue.length>0){const task=verifyQueue.shift();verifyActive++;Promise.resolve(checkSurahAvailability(task.readerId,task.idx)).finally(()=>{verifyActive--;processVerifyQueue();});}}
function showVerifyProgress(){const b=$('verifyProgressBar');if(b)b.style.display='flex';verifyCancelFlag=false;const c=$('cancelVerificationBtn'),r=$('retryFailedBtn'),m=$('manualVerifyBtn');if(c)c.style.display='inline-flex';if(r)r.style.display='none';if(m)m.style.display='none';}
function hideVerifyProgress(){const b=$('verifyProgressBar');if(!b)return;const s=$('verifyProgressStatus'),c=$('verifyProgressCount'),f=$('verifyProgressFill'),r=$('retryFailedBtn'),cb=$('cancelVerificationBtn'),m=$('manualVerifyBtn');if(verifyCancelFlag){if(s)s.innerHTML=svgIcon('ic-pause')+' تم إلغاء التحقق';if(c)c.textContent='';if(f)f.style.width='0%';if(cb)cb.style.display='none';if(r){r.style.display='inline-flex';r.innerHTML=svgIcon('ic-sync')+' إعادة التحقق';r.onclick=()=>{if(!networkOnline){toastWarning('لا يوجد اتصال بالإنترنت');return;}verifyCancelFlag=false;cb.style.display='inline-flex';r.style.display='none';if(m)m.style.display='none';startCheckingAvailability();};}if(m)m.style.display='none';b.style.display='flex';return;}if(!networkOnline){if(s)s.innerHTML=svgIcon('ic-exclamation-triangle')+' غير متصل';if(c)c.textContent='';if(f)f.style.width='0%';if(cb)cb.style.display='none';if(r){r.style.display='inline-flex';r.innerHTML=svgIcon('ic-sync')+' إعادة المحاولة';}if(m)m.style.display='none';b.style.display='flex';return;}b.style.display='none';Object.values(verifyAbortControllers).forEach(c=>c.abort());verifyAbortControllers={};if(cb)cb.style.display='inline-flex';if(r)r.style.display='none';if(m)m.style.display='none';}
function updateVerifyProgress(done,total){const s=$('verifyProgressStatus'),c=$('verifyProgressCount'),f=$('verifyProgressFill'),r=$('retryFailedBtn'),cb=$('cancelVerificationBtn'),m=$('manualVerifyBtn');if(!s||!c||!f)return;if(!networkOnline){s.innerHTML=svgIcon('ic-exclamation-triangle')+' غير متصل';c.textContent='';f.style.width='0%';if(cb)cb.style.display='none';if(r)r.style.display='inline-flex';if(m)m.style.display='none';showVerifyProgress();return;}if(done===0&&total===0){s.innerHTML=svgIcon('ic-hourglass')+' جاري التحقق...';c.textContent='0/114';f.style.width='0%';if(r)r.style.display='none';if(m)m.style.display='none';return;}if(done>=total){let fc=0;const rid=currentReader;if(surahAvailability[rid]){for(let i=0;i<TOTAL;i++)if(surahAvailability[rid][i]==='failed')fc++;}if(fc>0){s.textContent='تم التحقق، '+fc+' فشل';if(r){r.style.display='inline-flex';r.innerHTML=svgIcon('ic-sync')+' إعادة المحاولة ('+fc+')';r.onclick=retryFailedChecks;}if(m)m.style.display='none';}else{s.innerHTML=svgIcon('ic-chart-simple')+' الإحصائيات';if(r)r.style.display='none';if(m)m.style.display='none';const sb=$('statsBtn');if(sb){sb.classList.add('pulse');setTimeout(()=>sb.classList.remove('pulse'),5000);}setTimeout(()=>{if($('verifyProgressBar')?.style.display!=='none')hideVerifyProgress();},3000);}c.textContent=done+'/'+total;f.style.width='100%';return;}s.innerHTML=svgIcon('ic-hourglass')+' جاري التحقق... ('+Math.round((done/total)*100)+'%)';c.textContent=done+'/'+total;f.style.width=((done/total)*100)+'%';if(r)r.style.display='none';if(m)m.style.display='none';showVerifyProgress();}
