audio.addEventListener('ended',()=>{if(repeatMode==='one'){audio.currentTime=0;audio.play();return;}if(repeatMode==='all'){const vs=[];document.querySelectorAll('.surah-card').forEach(c=>{if(c.style.display!=='none'){const i=parseInt(c.dataset.idx);if(!isNaN(i))vs.push(i);}});if(vs.length===0){isPlaying=false;updatePlayerUI();return;}const ci=vs.indexOf(currentSurah),ni=(ci+1)%vs.length;toastInfo('السورة '+SN[vs[ni]]);playSurah(vs[ni],0);return;}isPlaying=false;updatePlayerUI();});
audio.addEventListener('play',()=>{isPlaying=true;updatePlayerUI();});
audio.addEventListener('pause',()=>{isPlaying=false;if(currentSurah>=0&&audio.currentTime>0)addSession('surah',currentReader,currentSurah,audio.currentTime);updatePlayerUI();});
function getSessions(){try{return JSON.parse(localStorage.getItem('sessions')||'[]');}catch(e){return[];}}
function saveSessions(s){localStorage.setItem('sessions',JSON.stringify(s));}
function addSession(type,reader,surah,time){let s=getSessions();if(type==='surah'||type==='reader'){s=s.filter(x=>x.type!==type);}else{const i=s.findIndex(x=>x.type===type&&x.reader===reader&&x.surah===surah);if(i!==-1)s.splice(i,1);}s.push({type,reader:reader||currentReader,surah:surah!==undefined?surah:-1,time:time||(audio.currentTime||0),timestamp:Date.now()});saveSessions(s);}
function removeSession(i){const s=getSessions();s.splice(i,1);saveSessions(s);}
function startSessionSaver(){if(sessionSaveInterval)clearInterval(sessionSaveInterval);sessionSaveInterval=setInterval(()=>{if(currentSurah>=0&&isPlaying&&audio.src&&!audio.paused&&audio.currentTime>0)addSession('surah',currentReader,currentSurah,audio.currentTime);},5000);}
function stopSessionSaver(){if(sessionSaveInterval){clearInterval(sessionSaveInterval);sessionSaveInterval=null;}}
function checkLastSession(){const sessions=getSessions();if(sessions.length===0)return;const now=Date.now();const valid=sessions.filter(s=>(now-s.timestamp)/(1000*60*60)<=48);if(valid.length===0)return;if(document.querySelector('.resume-overlay'))return;let html='';valid.forEach((s,index)=>{const rn=getReaderName(s.reader),ts=formatTime(s.time||0);if(s.type==='surah'){const sn=SN[s.surah]||'غير معروف';html+='<div class="resume-item"><div class="resume-item-title">'+svgIcon('ic-headphones')+' استماع: سورة '+sn+' ('+rn+')</div><div><button class="resume-btn" data-index="'+index+'" data-action="play" data-reader="'+s.reader+'" data-surah="'+s.surah+'" data-time="'+s.time+'">'+svgIcon('ic-play')+' متابعة ('+ts+')</button><button class="resume-btn" data-index="'+index+'" data-action="play" data-reader="'+s.reader+'" data-surah="'+s.surah+'" data-time="0">'+svgIcon('ic-redo')+' إعادة</button><button class="resume-ignore-btn" data-index="'+index+'">'+svgIcon('ic-stop-circle')+' تجاهل</button></div></div>';}else if(s.type==='reader'){const sn=SN[s.surah]||'غير معروف';html+='<div class="resume-item"><div class="resume-item-title">'+svgIcon('ic-book-open')+' قراءة: سورة '+sn+'</div><div><button class="resume-btn" data-index="'+index+'" data-action="read" data-surah="'+s.surah+'">'+svgIcon('ic-book-open')+' فتح</button><button class="resume-ignore-btn" data-index="'+index+'">'+svgIcon('ic-stop-circle')+' تجاهل</button></div></div>';}});if(!html)return;const overlay=document.createElement('div');overlay.className='resume-overlay';overlay.innerHTML='<div><h3 class="resume-title">'+svgIcon('ic-history')+' استئناف الجلسات السابقة</h3><div style="margin:1rem 0;">'+html+'</div><button class="btn-close-modal" id="sessionClose" style="width:100%;">إغلاق</button></div>';document.body.appendChild(overlay);document.body.style.overflow='hidden';overlay.querySelectorAll('.resume-btn').forEach(b=>{b.addEventListener('click',function(){const action=this.dataset.action,index=parseInt(this.dataset.index),rid=this.dataset.reader,surah=parseInt(this.dataset.surah),time=parseFloat(this.dataset.time)||0;if(action==='play'&&rid){selectReader(rid);setTimeout(()=>{if(rid===currentReader&&surah===currentSurah)currentSurah=-1;playSurah(surah,time);},300);removeSession(index);}else if(action==='read'){openReader(surah);removeSession(index);}const item=this.closest('.resume-item');if(item)item.remove();if(overlay.querySelectorAll('.resume-item').length===0){overlay.remove();document.body.style.overflow='';}});});overlay.querySelectorAll('.resume-ignore-btn').forEach(b=>{b.addEventListener('click',function(){const index=parseInt(this.dataset.index);removeSession(index);const item=this.closest('.resume-item');if(item)item.remove();if(overlay.querySelectorAll('.resume-item').length===0){overlay.remove();document.body.style.overflow='';}});});overlay.querySelector('#sessionClose').addEventListener('click',()=>{overlay.remove();document.body.style.overflow='';});}
function openReader(idx){if(idx<0||idx>113){toastError('رقم سورة غير صحيح');return;}const view=$('readerView'),title=$('readerTitle');if(!view||!title)return;currentReadingSurah=idx;const b=$('randomAyahBanner');if(b)b.classList.remove('visible');updateBannerToggleBtn();view.classList.add('visible');title.innerHTML=SN[idx]+' <span style="font-size:calc(0.65rem*var(--text-scale));opacity:0.6;color:var(--text-secondary);">('+ST[idx]+')</span>';applyMushafTheme();applyMushafFocusMode();loadSurahTextMushaf(idx,null);document.body.style.overflow='hidden';isReaderOpen=true;addSession('reader',currentReader,idx,0);pushWindow('readerView');history.pushState({modal:'readerView',level:windowStack.length},'');history.pushState({modal:'readerView',level:windowStack.length},'');$('readerSearchContainer').style.display='none';$('readerSearchInput').value='';$('readerSearchCount').textContent='0/0';clearSearchHighlights();updateReaderNavButtons();updateSyncIndicator();updateMiniPlayer();}
function openReaderWithAyah(idx,targetAyah){if(idx<0||idx>113){toastError('رقم سورة غير صحيح');return;}const view=$('readerView'),title=$('readerTitle');if(!view||!title)return;currentReadingSurah=idx;const b=$('randomAyahBanner');if(b)b.classList.remove('visible');updateBannerToggleBtn();view.classList.add('visible');title.innerHTML=SN[idx]+' <span style="font-size:calc(0.65rem*var(--text-scale));opacity:0.6;color:var(--text-secondary);">('+ST[idx]+')</span>';applyMushafTheme();applyMushafFocusMode();loadSurahTextMushaf(idx,targetAyah);document.body.style.overflow='hidden';isReaderOpen=true;addSession('reader',currentReader,idx,0);pushWindow('readerView');history.pushState({modal:'readerView',level:windowStack.length},'');history.pushState({modal:'readerView',level:windowStack.length},'');$('readerSearchContainer').style.display='none';$('readerSearchInput').value='';$('readerSearchCount').textContent='0/0';clearSearchHighlights();updateReaderNavButtons();updateSyncIndicator();updateMiniPlayer();}
function closeReader(){const v=$('readerView');if(v)v.classList.remove('visible');document.body.style.overflow='';isReaderOpen=false;const sessions=getSessions(),i=sessions.findIndex(s=>s.type==='reader'&&s.reader===currentReader&&s.surah===currentReadingSurah);if(i!==-1)removeSession(i);currentReadingSurah=-1;currentTiming=null;lastSyncedAyah=-1;windowStack=windowStack.filter(w=>w!=='readerView');if(windowStack.length===0){unlockBodyScroll();$('mainApp').classList.remove('blurred');}$('readerSearchContainer').style.display='none';$('readerSearchInput').value='';$('readerSearchCount').textContent='0/0';clearSearchHighlights();updateSyncIndicator();const mp=$('miniPlayer');if(mp)mp.classList.remove('visible');const rv=$('readerView');if(rv)rv.classList.remove('with-mini-player');}
function updateReaderNavButtons(){const p=$('readerPrevBtn'),n=$('readerNextBtn');if(!p||!n)return;p.classList.add('nav-btn');n.classList.add('nav-btn');p.classList.toggle('disabled',currentReadingSurah<=0);n.classList.toggle('disabled',currentReadingSurah>=113);}
function navigateReader(direction){if(currentReadingSurah<0){toastWarning('لم يتم فتح أي سورة');return;}const newIdx=currentReadingSurah+direction;if(newIdx<0){toastWarning('أنت في أول سورة');return;}if(newIdx>113){toastWarning('أنت في آخر سورة');return;}openReader(newIdx);setTimeout(()=>{updateReaderNavButtons();const v=$('readerView');if(v)v.scrollTop=0;},100);toastInfo('سورة '+SN[newIdx]+' ('+(newIdx+1)+')');}
function syncReaderWithPlayer(newIdx){if(!isReaderOpen){return;}if(newIdx<0||newIdx>113){return;}const view=$('readerView'),title=$('readerTitle');if(!view||!title)return;currentReadingSurah=newIdx;title.innerHTML=SN[newIdx]+' <span style="font-size:calc(0.65rem*var(--text-scale));opacity:0.6;color:var(--text-secondary);">('+ST[newIdx]+')</span>';currentTiming=null;lastSyncedAyah=-1;updateSyncIndicator();loadSurahTextMushaf(newIdx,null);updateReaderNavButtons();const b=$('readerSearchContainer');if(b)b.style.display='none';clearSearchHighlights();}
async function loadSurahTextMushaf(idx,targetAyah){const c=$('readerContent');if(!c)return;const ck='surah_'+idx;currentTiming=null;lastSyncedAyah=-1;updateSyncIndicator();if(SYNC_READERS[currentReader]){loadTimingData(currentReader,idx).then(t=>{currentTiming=t;updateSyncIndicator();});}if(textCache.has(ck)&&!targetAyah){c.innerHTML=textCache.get(ck);bindAyahClicks(c);applyMushafFont(mushafFont);applyMushafFontSize();applyMushafTheme();applyMushafFocusMode();applyMushafViewMode();return;}c.innerHTML='<div class="m-load"><div class="loading-spinner"></div><br>جاري تحميل السورة...</div>';try{const r=await fetch('https://api.alquran.cloud/v1/surah/'+(idx+1)+'/quran-uthmani');const d=await r.json();if(!d?.data?.ayahs)throw new Error('no data');const h=generateMushafHtml(d.data.ayahs,idx+1,SN[idx],targetAyah);c.innerHTML=h;if(!targetAyah){lruSet(textCache,ck,c.innerHTML);idbPut('texts','quranText_'+ck,{html:c.innerHTML,ts:Date.now()});}bindAyahClicks(c);applyMushafViewMode();if(targetAyah){setTimeout(()=>{scrollAyahToCenter(targetAyah,true);},350);setTimeout(()=>{scrollAyahToCenter(targetAyah,true);},900);}}catch(e){c.innerHTML='<div class="m-load">'+svgIcon('ic-exclamation-triangle')+'<br>فشل تحميل السورة<br><span style="font-size:calc(.8rem*var(--text-scale));color:var(--text-secondary);">تحقق من الاتصال بالإنترنت</span></div>';}}
function bindAyahClicks(c){c.querySelectorAll('.ayah-line').forEach(el=>{el.onclick=e=>{e.stopPropagation();const sn=+el.dataset.s,an=+el.dataset.a,txt=el.dataset.text||el.textContent.replace(/[٠-٩0-9]+/g,'').trim();currentAyahText=txt;showTafsir(sn,an);};});}
function adjFontSize(delta){fontsize=Math.round(Math.min(3.4,Math.max(1,fontsize+delta))*100)/100;localStorage.setItem('quranFontSize',String(fontsize));applyMushafFontSize();}
let readerSearchResults=[],readerSearchIndex=-1;
function clearSearchHighlights(){document.querySelectorAll('.ayah-line').forEach(el=>el.classList.remove('search-highlight','search-current'));}
function searchInCurrentSurah(q){const c=$('readerContent');if(!c)return;const ayahs=c.querySelectorAll('.ayah-line');clearSearchHighlights();readerSearchResults=[];readerSearchIndex=-1;if(!q||q.length<2){$('readerSearchCount').textContent='0/0';return;}const nq=normalizeText(q),terms=nq.split(' ').filter(t=>t.length>0),exact=terms.length>1;ayahs.forEach((ayah,i)=>{const text=ayah.dataset.text||ayah.textContent,nt=normalizeText(text);let m=false;if(exact){m=terms.every(t=>nt.includes(t));}else m=nt.includes(terms[0]);if(m){readerSearchResults.push(i);ayah.classList.add('search-highlight');}});if(readerSearchResults.length>0){readerSearchIndex=0;highlightReaderResult(readerSearchResults[0]);$('readerSearchCount').textContent='1/'+readerSearchResults.length;}else $('readerSearchCount').textContent='0/0';}
function highlightReaderResult(i){const ayahs=$('readerContent').querySelectorAll('.ayah-line');ayahs.forEach(el=>el.classList.remove('search-current'));if(i>=0&&i<ayahs.length){const a=ayahs[i];a.classList.add('search-current');a.scrollIntoView({behavior:'smooth',block:'center'});}}
async function renderTafsirContent(){const te=$('tafsirText'),t=$('tafsirTitle');if(!te||!t)return;t.textContent='تفسير الآية '+currentTafsirAyah+' من سورة '+SN[currentTafsirSurah-1];te.innerHTML='<div style="text-align:center;padding:2rem 0;"><div class="loading-spinner"></div><br>'+svgIcon('ic-hourglass')+' جاري تحميل التفسير...</div>';const res=await fetchTafsir(currentTafsirSurah,currentTafsirAyah,tafsirSource);const at=currentTafsirAyahText||'الآية غير متوفرة';te.innerHTML='<div style="margin-bottom:10px;padding:6px 10px;background:rgba(var(--gold-rgb),0.08);border-right:3px solid var(--gold);border-radius:6px;"><strong style="color:var(--gold-dark);font-size:calc(0.9rem*var(--text-scale));">'+svgIcon('ic-book-open')+' الآية:</strong><br><span style="color:var(--text);font-size:calc(0.95rem*var(--text-scale));line-height:1.7;font-family:\'Amiri Quran\',serif;">'+escapeHtml(at)+'</span></div><div style="margin-bottom:10px;padding:6px 10px;background:rgba(var(--gold-rgb),0.08);border-right:3px solid var(--gold);border-radius:6px;"><strong style="color:var(--gold-dark);font-size:calc(0.9rem*var(--text-scale));">'+svgIcon('ic-book')+' المفسر:</strong> <span style="color:var(--text);">'+escapeHtml(res.mufassir)+'</span></div><div style="color:var(--text);font-size:calc(0.95rem*var(--text-scale));line-height:1.9;">'+res.text+'</div>';const sb=$('tafsirShareBtn');if(sb)sb.onclick=()=>{const st='الآية: '+at+'\n— سورة '+SN[currentTafsirSurah-1]+' (الآية '+currentTafsirAyah+') —\n\nالمفسر: '+res.mufassir+'\nالتفسير: '+res.text+'\n\nتطبيق القرآن الكريم\nمنجد أمهز\nhttps://mamhaz.github.io/QuranKarim';if(navigator.share){try{navigator.share({title:'الآية '+currentTafsirAyah,text:st});}catch(e){}}else{try{navigator.clipboard.writeText(st);toastSuccess('تم نسخ التفسير');}catch(e){toastError('تعذر المشاركة');}}};saveReadingState(currentTafsirSurah,currentTafsirAyah);}
function updateCurrentAyahText(){const surahData=quranTexts?.find(s=>s.surah===currentTafsirSurah);if(surahData&&surahData.ayahs[currentTafsirAyah-1]){currentTafsirAyahText=surahData.ayahs[currentTafsirAyah-1].text;}else{currentTafsirAyahText='';}}
function updateTafsirNavButtons(){const p=$('tafsirPrevBtn'),n=$('tafsirNextBtn');if(!p||!n)return;const maxA=AYAH_COUNTS[currentTafsirSurah]||0;p.classList.toggle('disabled',currentTafsirAyah<=1);n.classList.toggle('disabled',currentTafsirAyah>=maxA);}
function navigateTafsirAyah(direction){if(!currentTafsirSurah)return;const maxA=AYAH_COUNTS[currentTafsirSurah]||0;const newAyah=currentTafsirAyah+direction;if(newAyah<1){toastWarning('هذه أول آية في السورة');return;}if(newAyah>maxA){toastWarning('هذه آخر آية في السورة');return;}currentTafsirAyah=newAyah;updateCurrentAyahText();renderTafsirContent();updateTafsirNavButtons();const tt=$('tafsirText');if(tt)tt.scrollTop=0;}
async function showTafsir(surah,ayah){const m=$('tafsirModal');if(!m)return;currentTafsirSurah=surah;currentTafsirAyah=ayah;currentTafsirAyahText=currentAyahText;openModalUniversal('tafsirModal');document.querySelectorAll('#tafsirTabs .tafsir-tab').forEach(t=>t.classList.toggle('active',t.dataset.source===tafsirSource));updateTafsirNavButtons();renderTafsirContent();}
function showSearchLoading(){const c=$('readerSearchResults');if(!c)return;c.innerHTML='<div class="search-loading-indicator"><div class="search-spinner"></div><div class="search-loading-text">'+svgIcon('ic-search')+' جاري البحث في القرآن الكريم...</div></div>';c.classList.add('show');}
function renderAyahSearchResults(results,query){const c=$('readerSearchResults');c.innerHTML='';c.classList.add('show');if(results.length===0){c.innerHTML='<div class="reader-search-item ayah-no-result-msg">'+svgIcon('ic-search')+' لا توجد آيات تطابق "<strong>'+escapeHtml(query)+'</strong>"</div>';return;}let h='';results.forEach(r=>{h+='<div class="reader-search-item ayah-result-item" data-surah="'+r.surah+'" data-ayah="'+r.ayah+'"><div class="ayah-result-content"><span class="ayah-text">'+highlightText(r.text,query)+'</span><div class="ayah-meta"><span class="ayah-location">'+svgIcon('ic-book-open')+' '+escapeHtml(r.surahName)+' (الآية '+r.ayah+')</span></div></div></div>';});c.innerHTML='<div class="ayah-results-header"><span class="results-title">'+svgIcon('ic-book')+' نتائج البحث: '+results.length+'</span><button class="close-results-btn" id="closeAyahResults">'+svgIcon('ic-times')+'</button></div>'+h;c.querySelector('#closeAyahResults').addEventListener('click',()=>{c.classList.remove('show');$('searchMainInput').value='';$('searchClearBtn').classList.remove('visible');$('searchResultsInfo').classList.remove('show');});c.querySelectorAll('.ayah-result-item').forEach(item=>{item.addEventListener('click',function(){const s=parseInt(this.dataset.surah),a=parseInt(this.dataset.ayah);c.classList.remove('show');$('searchMainInput').value='';$('searchClearBtn').classList.remove('visible');$('searchResultsInfo').classList.remove('show');openReaderWithAyah(s-1,a);});});}
function updateSearchResultsInfo(filter){const info=$('searchResultsInfo');if(!info)return;const q=(filter||'').trim();if(!q){info.classList.remove('show');return;}if(searchTarget==='readers'){let c=R.filter(r=>r.name.indexOf(q.toLowerCase())!==-1);if(readersWithRadioOnly)c=c.filter(r=>r.radio&&r.radio.length>0);info.textContent='تم العثور على '+c.length+' قارئ';info.classList.add('show');}else if(searchTarget==='surahs'){const parts=q.split(' ');const c=SN.filter(n=>parts.every(p=>n.indexOf(p)!==-1)).length;info.textContent='تم العثور على '+c+' سورة';info.classList.add('show');}else if(searchTarget==='ayahs'){info.textContent='ابحث عن آية (حرفين على الأقل)';info.classList.add('show');}}
function updateReaderSearchResults(filter){const c=$('readerSearchResults');if(!c)return;const q=(filter||'').trim().toLowerCase();if(!q||searchTarget!=='readers'){c.classList.remove('show');return;}let f=R.filter(e=>e.name.indexOf(q)!==-1);if(readersWithRadioOnly){f=f.filter(e=>e.radio&&e.radio.length>0);}if(f.length===0){c.innerHTML='<div class="reader-search-item reader-no-result-msg">'+svgIcon('ic-search')+' لا توجد نتائج</div>';}else{c.innerHTML=f.map(e=>'<div class="reader-search-item" data-reader="'+e.id+'">'+e.name+'</div>').join('');c.querySelectorAll('.reader-search-item[data-reader]').forEach(item=>{item.addEventListener('click',()=>{selectReader(item.dataset.reader);$('searchMainInput').value='';c.classList.remove('show');$('searchResultsInfo').classList.remove('show');$('searchClearBtn').classList.remove('visible');});});}c.classList.add('show');}
function searchSurahs(query){const grid=$('surahGrid');if(!grid)return;if(grid.children.length===0){renderAllSurahs(true);requestAnimationFrame(()=>searchSurahs(query));return;}const t=query.trim().toLowerCase(),cards=grid.querySelectorAll('.surah-card');if(!t){cards.forEach(c=>c.style.display='flex');const n=$('noSurahResult');if(n)n.remove();return;}const parts=t.split(' ').filter(p=>p.length>0);let found=false,matched=[];cards.forEach(c=>{const name=c.querySelector('.surah-name').textContent.toLowerCase();const m=parts.every(p=>name.includes(p));c.style.display=m?'flex':'none';if(m){found=true;matched.push(c);}});let n=$('noSurahResult');if(!found){if(!n){n=document.createElement('div');n.id='noSurahResult';n.className='no-surah-result';grid.appendChild(n);}n.innerHTML=svgIcon('ic-search')+' لا توجد سور تطابق بحثك';n.style.display='block';}else if(n)n.remove();if(matched.length===1){matched[0].scrollIntoView({behavior:'smooth',block:'center'});matched[0].style.background='rgba(201,168,76,0.15)';setTimeout(()=>matched[0].style.background='',2000);}}
function showFavReadersModal(){const fl=R.filter(r=>favReaders.indexOf(r.id)!==-1);if(fl.length===0){toastInfo('لا يوجد قراء مفضلون');return;}const o=document.createElement('div');o.className='tafsir-modal show';o.style.display='flex';o.innerHTML='<div class="tafsir-content"><h3>'+svgIcon('ic-star')+' مفضلة القراء</h3><div class="modal-list">'+fl.map(r=>'<div class="modal-item" data-id="'+r.id+'"><span class="item-name">'+r.name+'</span><span class="item-action">'+svgIcon('ic-chevron-left')+'</span></div>').join('')+'</div><button class="btn-close-modal" id="favReadersClose">'+svgIcon('ic-times')+' إغلاق</button></div>';document.body.appendChild(o);document.body.style.overflow='hidden';$('mainApp').classList.add('blurred');const close=()=>{o.remove();document.body.style.overflow='';$('mainApp').classList.remove('blurred');windowStack=windowStack.filter(w=>w!=='favReadersModal');};o.querySelectorAll('.modal-item').forEach(i=>i.addEventListener('click',()=>{selectReader(i.dataset.id);close();}));o.querySelector('#favReadersClose').addEventListener('click',close);o.addEventListener('click',e=>{if(e.target===e.currentTarget)close();});}
