function updateSelectionStats(){const checked=document.querySelectorAll('#selectionGrid input[type="checkbox"]:checked');$('selCount').textContent=checked.length;const rid=currentReader;let totalSize=0;checked.forEach(cb=>{const idx=parseInt(cb.dataset.idx),url=getReaderUrl(rid,idx);if(url){const s=getFileSizeFromCache(url);if(s>0)totalSize+=s;}});$('selTotalSize').textContent=formatSize(totalSize)||'0';}
function showDeleteConfirm(idx){if(idx<0||idx>113){toastError('رقم سورة غير صحيح');return;}confirmIdx=idx;const rid=currentReader,rn=getReaderName(rid),sn=SN[idx]||'سورة '+(idx+1);const fs=downloaded[rid]?.[idx]?.size||0,se=$('dlDeleteSize');se.textContent='جاري حساب الحجم...';se.style.color='var(--text-secondary)';$('dlDeleteSurah').textContent=sn;$('dlDeleteReader').textContent='القارئ: '+rn;if(fs>0){se.innerHTML=svgIcon('ic-box')+' الحجم: <strong>'+formatSize(fs)+'</strong>';se.style.color='var(--text)';}else{const url=getReaderUrl(rid,idx);if(url){caches.open('quran-audio').then(c=>c.match(url).then(r=>{if(r)r.blob().then(b=>{const s=b.size;if(s>0){if(!downloaded[rid])downloaded[rid]={};if(downloaded[rid][idx])downloaded[rid][idx].size=s;else downloaded[rid][idx]={downloaded:true,size:s,date:new Date().toISOString(),lastPlayedAt:null};debouncedSaveState();se.innerHTML=svgIcon('ic-box')+' الحجم: <strong>'+formatSize(s)+'</strong>';se.style.color='var(--text)';}else se.textContent='الحجم: غير معروف';}).catch(()=>se.textContent='الحجم: غير معروف');else se.textContent='الحجم: غير معروف';}));}else se.textContent='الحجم: غير معروف';}$('dlDeleteMulti').checked=false;$('dlDeleteBtnText').textContent='تأكيد الحذف';openModalUniversal('deleteConfirmModal');}
