if('serviceWorker'in navigator){try{const swCode="\nconst CACHE_NAME='quran-v5-0';\nconst urlsToCache=['.','index.html'];\nself.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE_NAME).then(c=>c.addAll(urlsToCache)).then(()=>self.skipWaiting()));});\nself.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE_NAME).map(k=>caches.delete(k)))));});\nself.addEventListener('fetch',e=>{e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request)));});\n";const sb2=new Blob([swCode],{type:'application/javascript'});const su=URL.createObjectURL(sb2);navigator.serviceWorker.register(su,{scope:'.'}).then(()=>URL.revokeObjectURL(su)).catch(()=>{navigator.serviceWorker.register('service-worker.js',{scope:'.'}).catch(()=>{});});}catch(e){}}
